pub fn wildlife_purpose() -> &'static str {
    "Wildlife sightings for bear, elk, bird, reptile, closure, and safety events monitored across camps, trails, and shoreline zones."
}

pub fn wildlife_summary() -> String {
    let campsites = wildlife_sightings();
    let shard_total: u32 = campsites.iter().map(|item| item.shard).sum();
    let record_total: u32 = campsites.iter().map(|item| item.survey).sum();
    let pressure_total: u32 = campsites.iter().map(|item| item.pressure).sum();
    format!("wildlife count={} shard={} rec={} pressure={}", campsites.len(), shard_total, record_total, pressure_total)
}

pub fn wildlife_family_window(family: &str, limit: usize) -> Vec<WildlifeSighting> {
    wildlife_sightings().into_iter().filter(|item| item.family == family).take(limit).collect()
}

pub fn wildlife_weighted_total(seed: u32) -> u64 {
    wildlife_sightings().into_iter().enumerate().map(|(index, item)| {
        let bias = (seed as u64 + index as u64 % 31) + 1;
        bias * (item.shard as u64 + item.survey as u64 * 3 + item.pressure as u64 * 5)
    }).sum()
}

pub fn wildlife_nearest(shard: u32, survey: u32) -> Option<WildlifeSighting> {
    wildlife_sightings().into_iter().min_by_key(|item| {
        let a = item.shard.abs_diff(shard) as u64;
        let b = item.survey.abs_diff(survey) as u64;
        a * 7 + b * 3 + item.pressure as u64
    })
}

pub fn wildlife_note_digest(limit: usize) -> Vec<String> {
    wildlife_sightings().into_iter().take(limit).map(|item| format!("{}:{}:{}", item.key, item.family, item.note)).collect()
}
